<script setup>defineProps({ status: Object, busy: Boolean }); defineEmits(['validate']);</script>
<template><section class="cg-validation"><div><strong>{{ status.dataVerified ? 'Data Verified' : 'Validation Error' }}</strong><span>{{ status.ready ? 'Artwork, teks, dan sisi belakang lolos pemeriksaan.' : 'Perlu diselesaikan sebelum cetak:' }}</span></div><ul v-if="status.errors.length"><li v-for="error in status.errors" :key="error">{{ error }}</li></ul><button type="button" :disabled="busy" @click="$emit('validate')">{{ busy ? 'Memeriksa…' : 'Periksa artwork & render' }}</button></section></template>
